package jp.example.variablecolorlight;
import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.item.ItemStack;
public final class MessageSetItemBBCL implements IMessage{
    private int kelvin,r,g,b,level;private boolean mode,redstoneControlled;public MessageSetItemBBCL(){}public MessageSetItemBBCL(boolean m,boolean redstone,int k,int r,int g,int b,int l){mode=m;redstoneControlled=redstone;kelvin=k;this.r=r;this.g=g;this.b=b;level=l;}public void toBytes(ByteBuf o){o.writeBoolean(mode);o.writeBoolean(redstoneControlled);o.writeShort(kelvin);o.writeByte(r);o.writeByte(g);o.writeByte(b);o.writeByte(level);}public void fromBytes(ByteBuf i){mode=i.readBoolean();redstoneControlled=i.readBoolean();kelvin=i.readUnsignedShort();r=i.readUnsignedByte();g=i.readUnsignedByte();b=i.readUnsignedByte();level=i.readUnsignedByte();}
    public static final class Handler implements IMessageHandler<MessageSetItemBBCL,IMessage>{public IMessage onMessage(MessageSetItemBBCL m,MessageContext c){EntityPlayerMP p=c.getServerHandler().playerEntity;ItemStack s=p.getHeldItem();if(!VariableColorLight.isEditableLightItem(s))return null;ItemStackLightData d=new ItemStackLightData(s);d.setKelvin(m.kelvin);d.setRgb(m.r,m.g,m.b);d.setRgbMode(m.mode);d.setRedstoneControlled(s.getItem()==net.minecraft.item.Item.getItemFromBlock(VariableColorLight.lamp)&&m.redstoneControlled);d.setLevel(m.level);p.inventory.markDirty();return null;}}
}
